const INVENTORY_CATEGORIES=['Medical','Drug','Booster','Energy Drink','Candy','Alcohol','Temporary','Enhancer','Tool','Primary','Secondary','Melee','Defensive','Clothing','Other','Collectible','Material','Car','Book','Special','Supply Pack','Artifact','Flower','Jewelry','Plushie'];
