 if(type==='status'){const m=text.match(/^(.+?) is (stunned|withered|slowed|suppressed|demoralized|disarmed)/i);target=norm(m?.[1]);actor=target===p.a?p.b:target===p.b?p.a:null;effect=({stunned:'Stun',withered:'Wither',slowed:'Slow',suppressed:'Suppress',demoralized:'Demoralize',disarmed:'Disarm'})[m?.[2].toLowerCase()];}
